{"query":"{ __type(name: \"Project\") { fields { name args { name type { name kind ofType { name kind } } } } } }"}
EOF
curl -s -X POST https://api.linear.app/graphql -H "Content-Type: application/json" -d @q2.json | python3 -c "
import json,sys
d=json.load(sys.stdin)
for f in d['data']['__type']['fields']:
    if f['name'] in ('projects','projectMilestones','issues','milestones','targetDate'):
        print(f['name'], [ (a['name'], a['type']) for a in f['args']])
"

